#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* Format: "TLV1" then records of [type][len][len bytes of value]. */
struct rec { char name[16]; uint32_t count; };

int parse_tlv(const uint8_t *buf, size_t n, struct rec *out) {
    if (n < 4 || memcmp(buf, "TLV1", 4) != 0) return -1;
    size_t i = 4;
    while (i + 2 <= n) {
        uint8_t type = buf[i], len = buf[i + 1];
        i += 2;
        if (i + len > n) return -1;           /* value fits in input */
        if (type == 'N') {
            memcpy(out->name, buf + i, len);  /* BUG: len can exceed 16 */
        } else if (type == 'C' && len == 4) {
            memcpy(&out->count, buf + i, 4);
        }
        i += len;
    }
    return 0;
}

