// Build a structurally valid TLV file, so every run gets past the magic check.
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  FuzzedDataProvider fdp(data, size);
  std::vector<uint8_t> file = {'T', 'L', 'V', '1'};
  while (fdp.remaining_bytes() > 0) {
    uint8_t type = fdp.PickValueInArray({'N', 'C', 'X'});
    std::string value = fdp.ConsumeRandomLengthString(255);
    file.push_back(type);
    file.push_back(static_cast<uint8_t>(value.size()));
    file.insert(file.end(), value.begin(), value.end());
  }
  rec r = {};
  parse_tlv(file.data(), file.size(), &r);
  return 0;
}

